/* @verseva/design theme preset: cobalt. One accent, matte (law 3); saturation
   is a theme axis. Every pair below is contrast-gate proven:
   verseva-contrast-gate --tokens tokens.css --tokens themes/cobalt.css */
[data-brand="cobalt"] {
  --accent: #4D9FFF;
  --accent-hover: #6FB1FF;
  --accent-ink: #06101C;
  --focus: #4D9FFF;
}
[data-brand="cobalt"][data-theme="light"] {
  --accent: #1D4ED8;
  --accent-hover: #1A3FB0;
  --accent-ink: #FFFFFF;
  --focus: #1D4ED8;
}
